CREATE TABLE IF NOT EXISTS wrld_profile_extras(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,age INTEGER NOT NULL DEFAULT 0 CHECK(age=0 OR age BETWEEN 13 AND 120),interests TEXT NOT NULL DEFAULT '[]',status_emoji TEXT NOT NULL DEFAULT '',status_text TEXT NOT NULL DEFAULT '',discoverable INTEGER NOT NULL DEFAULT 0 CHECK(discoverable IN(0,1)));
CREATE TABLE IF NOT EXISTS wrld_world_quest_claims(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,quest TEXT NOT NULL,day INTEGER NOT NULL,claimed_at INTEGER NOT NULL,PRIMARY KEY(user_id,quest,day));